cy">{{ $settings->return_policy }}</textarea></label><label class="full">Privacy policy<textarea name="privacy_policy">{{ $settings->privacy_policy }}</textarea></label></div><label class="check"><input name="checkout_enabled" type="checkbox" value="1" @checked($settings->checkout_enabled)>Enable checkout when all independent deployment and readiness gates pass.</label><button class="button">Save marketplace settings</button></form>
